function getToken() { return sessionStorage.getItem(ACCESS_KEY) || localStorage.getItem(ACCESS_KEY) || ''; }
function getRefreshToken() { return sessionStorage.getItem(REFRESH_KEY) || localStorage.getItem(REFRESH_KEY) || ''; }
function setSession(session, remember=false) {
  sessionStorage.removeItem(ACCESS_KEY); sessionStorage.removeItem(REFRESH_KEY);
  localStorage.removeItem(ACCESS_KEY); localStorage.removeItem(REFRESH_KEY);
  const storage=remember?localStorage:sessionStorage;
  if (session?.access_token) storage.setItem(ACCESS_KEY, session.access_token);
  if (session?.refresh_token) storage.setItem(REFRESH_KEY, session.refresh_token);
  state.authenticated = Boolean(session?.access_token || getToken());
}
function clearSession() {
  sessionStorage.removeItem(ACCESS_KEY); sessionStorage.removeItem(REFRESH_KEY);
  localStorage.removeItem(ACCESS_KEY); localStorage.removeItem(REFRESH_KEY);
  state.authenticated=false; state.profile=null; state.portfolio=null;
  state.summary={cash_balance:null,market_value:null,total_value:null,open_positions:0};
  state.instruments=[];state.positions=[];state.orders=[];state.account_requests=[];state.activity=[];state.watchlist=[];state.price_alerts=[];state.notifications=[];state.support_tickets=[];state.portfolio_models=[];state.research_articles=[];
  state.admin={summary:{users:0,pending_requests:0,open_tickets:0},users:[],orders:[],requests:[],instruments:[],support_tickets:[],audit:[],portfolio_models:[],research_articles:[]};
}
class ApiError extends Error { constructor(message, status=0, code='API_ERROR'){super(message);this.status=status;this.code=code;} }
async function rawRequest(path, options={}, token='') {
  const headers={...(options.headers||{})};
  if (options.body && !headers['Content-Type']) headers['Content-Type']='application/json';
  if (token) headers.Authorization=`Bearer ${token}`;
  let response;
  try { response=await fetch(`${API_BASE}${path}`,{...options,headers}); }
  catch (_) { throw new ApiError('Could not reach the account service. Check the API URL and backend status.'); }
  const payload=await response.json().catch(()=>({}));
  if(!response.ok) throw new ApiError(payload.error||`Request failed (${response.status}).`,response.status,payload.code);
  return payload;
}
async function refreshSession() {
  const refresh=getRefreshToken(); if(!refresh) return false;
  try { const remember=Boolean(localStorage.getItem(ACCESS_KEY));const result=await rawRequest('/auth/refresh',{method:'POST',body:JSON.stringify({refresh_token:refresh})}); setSession(result.session,remember); return true; }
  catch (_) { clearSession(); return false; }
}
async function api(path, options={}) {
  const token=options.auth===false?'':getToken();
  const fetchOptions={method:options.method||'GET',headers:{...(options.headers||{})}};
  if(options.body!==undefined) fetchOptions.body=JSON.stringify(options.body);
  try { return await rawRequest(path,fetchOptions,token); }
  catch(error) {
    if(error.status===401 && token && options.refresh!==false && !path.startsWith('/auth/')) {
      if(await refreshSession()) return rawRequest(path,fetchOptions,getToken());
      navigate('/login',true);
    }
    throw error;
  }
}
function money(value,currency='USD') {
  if(value===null||value===undefined||value==='') return '—';
  const amount=Number(value); if(!Number.isFinite(amount))return '—';
  try{return new Intl.NumberFormat(undefined,{style:'currency',currency:currency||'USD',maximumFractionDigits:2}).format(amount);}catch(_){return `${amount.toFixed(2)} ${currency||'USD'}`;}
}
function num(value,digits=2) { if(value===null||value===undefined||value==='')return '—';const n=Number(value);return Number.isFinite(n)?new Intl.NumberFormat(undefined,{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(n):'—'; }
function dateText(value) { if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?esc(value):d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}); }
function initials(value='') { return String(value).trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()||'U'; }
function classLabel(value='') { return ({stocks:'Stocks',government_bonds:'Government bonds',commodities:'Commodities'})[value]||value||'—'; }
function classSlug(value='') { return value==='government_bonds'?'bond':value==='commodities'?'commodity':''; }
function assetSymbol(instrument) { return instrument?.symbol||'—'; }
function markFor(instrument) { return `<span class="asset-logo ${classSlug(instrument?.asset_class)}">${esc((instrument?.symbol||'?').slice(0,4))}</span>`; }
function percent(value) { const v=Number(value);return Number.isFinite(v)?`<span class="${v>=0?'pos':'neg'}">${v>=0?'+':''}${num(v,2)}%</span>`:'—'; }
function toast(title,message) {
  let stack=$('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.appendChild(stack);}
  const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('checkCircle')}<div><strong>${esc(title)}</strong><p>${esc(message)}</p></div>`;stack.appendChild(el);
  setTimeout(()=>{el.style.opacity='0';el.style.transform='translateX(8px)';setTimeout(()=>el.remove(),220);},4000);
}
function emptyState(title,description,iconName='document',action='') {
  return `<div class="empty-state"><span class="empty-icon">${icon(iconName)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<div style="margin-top:13px">${action}</div>`:''}</div>`;
}
function notice(text,kind='') { return `<div class="notice ${kind}">${icon('info')}<div>${esc(text)}</div></div>`; }
function riskNotice(text='Account balances and activity are retrieved from the connected database. Market prices and investment services require verified data and provider integrations.') { return `<div class="notice">${icon('shield')}<div>${esc(text)}</div></div>`; }
function brandMarkup(){return `<a class="brand" href="/" data-nav="/"><span class="brand-mark">${icon('mark')}</span><span class="brand-name">OLTREVIX<small>BROKERAGE</small></span></a>`;}
function formatInstrumentPrice(item){if(!item)return '—';if(item.quote_price==null)return '—';const suffix=item.asset_class==='government_bonds'?' per 100 face':'';return `${money(item.quote_price,item.currency)}${suffix}`;}
function statusPill(status='') { const s=String(status||'pending').toLowerCase();return `<span class="status ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`; }
function apiStatusNotice(){if(!state.apiHealth)return '';if(!state.apiHealth.configured)return notice('Account database is not connected yet. Set the Supabase environment variables on the backend before enabling sign-in or loading account data.','warning');return '';}

